// EXPERIMENT ONLY. Generates an isolated copy of the official engine with proposal B ("an egg receives a
// challenge as power 0 / wisdom 0") into ../.variant-egg00/. The official engine.mjs, cpu-observation.mjs,
// auto-progress.mjs and card definitions are only read, never written. The generated directory is not committed,
// not in tools/pages/allowlist.json and not imported by any runtime file.
// Usage: node tools/make-variant.mjs   (prints the sha256 of every source and generated file)
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';import {createHash} from 'node:crypto';
import {dirname,join} from 'node:path';import {fileURLToPath} from 'node:url';
const here=dirname(fileURLToPath(import.meta.url)),game=join(here,'..','..'),out=join(here,'..','.variant-egg00');
const sha=t=>createHash('sha256').update(t).digest('hex');
const EGG="{power:0,wisdom:0}";
// Each patch must match exactly once in the official source, otherwise generation stops.
const PATCHES={
 'engine.mjs':[
  // 1. The declarer still needs a main; the opponent may be an egg.
  ["if(b.main&&o.board.main&&!p.challengeUsed)","if(b.main&&!p.challengeUsed)"],
  // 2. An egg participant is recorded as null with no generation.
  ["generations:{A:s.cards[s.players.A.board.main].generation,B:s.cards[s.players.B.board.main].generation}",
   "generations:{A:s.players.A.board.main?s.cards[s.players.A.board.main].generation:null,B:s.players.B.board.main?s.cards[s.players.B.board.main].generation:null}"],
  // 3. Abort check: an egg participant is still "present" while the main slot stays empty.
  ["(s.challenge.generations&&s.cards[s.challenge.participants[a]].generation!==s.challenge.generations[a])",
   "(s.challenge.generations&&s.challenge.participants[a]&&s.cards[s.challenge.participants[a]].generation!==s.challenge.generations[a])"],
  // 4. Comparison and quick-play conditions read an egg as 0/0.
  ["const values={A:stats(s,'A')[s.challenge.parameter],B:stats(s,'B')[s.challenge.parameter]}",
   `const values={A:(stats(s,'A')??${EGG})[s.challenge.parameter],B:(stats(s,'B')??${EGG})[s.challenge.parameter]}`],
  ["values=s.challenge?{A:stats(s,'A')?.[s.challenge.parameter],B:stats(s,'B')?.[s.challenge.parameter]}",
   `values=s.challenge?{A:(stats(s,'A')??${EGG})[s.challenge.parameter],B:(stats(s,'B')??${EGG})[s.challenge.parameter]}`],
  // 5. Public view shows an egg as 0/0 so the unchanged CPU challenge evaluation can price it.
  ["stats:stats(s,a),board","stats:stats(s,a)??"+EGG+",board"],
 ],
 'cpu-observation.mjs':[],'auto-progress.mjs':[],
};
const LOCAL=new Set(Object.keys(PATCHES));
mkdirSync(out,{recursive:true});const report={generatedAt:'deterministic',sources:{},generated:{}};
for(const [file,patches] of Object.entries(PATCHES)){
 let t=readFileSync(join(game,file),'utf8');report.sources[file]=sha(t);
 for(const [from,to] of patches){const n=t.split(from).length-1;if(n!==1)throw Error(`${file}: patch matched ${n} times: ${from.slice(0,60)}`);t=t.replace(from,()=>to);}
 // Imports of the three local copies stay local; every other module is the official one, read-only.
 t=t.replace(/from '\.\/([\w-]+\.mjs)'/g,(m,f)=>LOCAL.has(f)?m:`from '../../${f}'`);
 t='// GENERATED BY egg-wait-study-20261026/tools/make-variant.mjs — EXPERIMENT ONLY (proposal B). Do not import from runtime.\n'+t;
 writeFileSync(join(out,file),t);report.generated[file]=sha(t);
}
writeFileSync(join(out,'package.json'),'{"type":"module"}\n');
console.log(JSON.stringify(report,null,1));
